def crear_roles_de_nivel(apps, schema_editor):
    """Un rol por cada nivel que ya existe, sin permisos, y el primer reparto:
    quien ocupa un cargo recibe en su membresía el rol del nivel de su unidad."""
    Group = apps.get_model("auth", "Group")
    Nivel = apps.get_model("organizacion", "NivelJerarquico")
    Perfil = apps.get_model("organizacion", "DatosDeContacto")
    Membresia = apps.get_model("empresas", "MembresiaEmpresa")
    for nivel in Nivel.objects.select_related("empresa").filter(rol__isnull=True):
        base = f"{nivel.empresa.nombre} · {nivel.nombre}"[:150]
        nombre, n = base, 2
        while Group.objects.filter(name__iexact=nombre).exists():
            nombre = f"{base} ({n})"[:150]
            n += 1
        nivel.rol = Group.objects.create(name=nombre)
        nivel.save(update_fields=["rol"])
    for perfil in Perfil.objects.filter(cargo__unidad__nivel__rol__isnull=False).select_related(
        "cargo__unidad__nivel"
    ):
        membresia = Membresia.objects.filter(
            usuario_id=perfil.usuario_id, empresa_id=perfil.empresa_id
        ).first()
        if membresia is not None:
            membresia.roles.add(perfil.cargo.unidad.nivel.rol_id)


